    /// <summary>
    /// Modify based on the user selected InventLocation
    /// </summary>
    /// <param name="sender">Form datasource</param>
    /// <param name="e">Data field</param>
    [FormDataFieldEventHandler(formDataFieldStr(InventJournalLossProfit, InventDim, InventLocationId), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventLocationId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormRun             fr                  = sender.datasource().formRun();
        InventDim           inventDim           = fr.dataSource(formdatasourcestr(InventJournalLossProfit, InventDim)).cursor();
        InventJournalTrans  inventJournalTrans  = fr.dataSource(formDataSourceStr(InventJournalLossProfit, InventJournalTrans)).cursor();

        inventJournalTrans.metCopyDimensionfromWarehosue(inventDim);
    }

